// config/AppConfig.java
// ============================================================
package com.example.deptsum.config;

import com.example.deptsum.service.DeptSumService;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class AppConfig {

    /**
     * Runs the DEPTSUM job automatically on start-up,
     * mirroring COBOL MAIN-PARA / STOP RUN behaviour.
     */
    @Bean
    ApplicationRunner deptsumRunner(DeptSumService deptsumService) {
        return (ApplicationArguments args) -> deptsumService.run();
    }
}

