package com.example.deptsum.domain;

import jakarta.persistence.*;
import lombok.*;
import java.math.BigDecimal;

/**
 * Maps to the EMPREC copybook fields used by DEPTSUM.
 * Table: employee
 */
@Entity
@Table(name = "employee")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Employee {

    /** EMP-ID  PIC X(6) */
    @Id
    @Column(name = "emp_id", length = 6, nullable = false)
    private String empId;

    /** EMP-NAME  PIC X(20) */
    @Column(name = "emp_name", length = 20)
    private String empName;

    /** EMP-DEPT  PIC X(10) – primary sort key */
    @Column(name = "emp_dept", length = 10, nullable = false)
    private String empDept;

    /** EMP-SALARY  PIC 9(7)V99 */
    @Column(name = "emp_salary", precision = 9, scale = 2, nullable = false)
    private BigDecimal empSalary;
}

