package com.example.deptsum.domain;

import lombok.*;
import java.math.BigDecimal;

/**
 * Value object carrying per-department aggregates
 * (mirrors WS-DEPT-COUNT, WS-DEPT-TOTAL, WS-DEPT-AVG).
 */
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class DepartmentSummary {
    private String department;   // DTL-DEPT  PIC X(12)
    private int    headCount;    // DTL-COUNT PIC ZZ9
    private BigDecimal totalSalary;  // DTL-TOTAL PIC ZZ,ZZZ,ZZ9.99
    private BigDecimal avgSalary;    // DTL-AVG   PIC Z,ZZZ,ZZ9.99
}

