package com.example.deptsum.repository;

import com.example.deptsum.domain.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, String> {

    /**
     * Returns all employees sorted by department then by employee-id,
     * reproducing the COBOL SORT … ON ASCENDING KEY EMP-DEPT
     *                                  ASCENDING KEY EMP-ID.
     */
    @Query("SELECT e FROM Employee e ORDER BY e.empDept ASC, e.empId ASC")
    List<Employee> findAllSortedByDeptThenId();
}

