package com.example.deptsum.service;

import com.example.deptsum.domain.Employee;
import com.example.deptsum.repository.EmployeeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Parses the fixed-width flat file (employees.dat) and persists
 * each record to PostgreSQL, replacing the COBOL EMP-FILE / FD.
 *
 * EMPREC layout assumed from copybook (total 54 chars):
 *   EMP-ID     PIC X(06)  pos 1-6
 *   EMP-NAME   PIC X(20)  pos 7-26
 *   EMP-DEPT   PIC X(10)  pos 27-36
 *   EMP-SALARY PIC 9(7)V99 pos 37-45  (9 numeric digits, implied decimal)
 *   FILLER     PIC X(09)  pos 46-54
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class EmployeeFileParser {

    private final EmployeeRepository employeeRepository;

    @Value("${deptsum.input.file}")
    private String inputFilePath;

    /**
     * Loads the flat file into the employee table.
     * Idempotent: clears existing rows before inserting.
     */
    @Transactional
    public int loadFile() throws IOException {
        Path path = Path.of(inputFilePath);
        if (!Files.exists(path)) {
            throw new IOException("Input file not found: " + path.toAbsolutePath());
        }

        employeeRepository.deleteAllInBatch();

        List<Employee> batch = new ArrayList<>();
        int lineNo = 0;

        try (BufferedReader br = new BufferedReader(new FileReader(path.toFile()))) {
            String raw;
            while ((raw = br.readLine()) != null) {
                lineNo++;
                // Pad / trim to exactly 54 characters
                String line = String.format("%-54s", raw);

                String empId     = line.substring(0,  6).trim();
                String empName   = line.substring(6,  26).trim();
                String empDept   = line.substring(26, 36).trim();
                // Salary stored without decimal point in flat file (9(7)V99 = 9 digits)
                String salStr    = line.substring(36, 45).trim();

                if (empId.isEmpty()) {
                    log.warn("Skipping blank line {}", lineNo);
                    continue;
                }

                BigDecimal salary;
                try {
                    // Implied decimal: last two digits are cents
                    long salLong = Long.parseLong(salStr);
                    salary = BigDecimal.valueOf(salLong, 2); // divide by 100
                } catch (NumberFormatException e) {
                    log.warn("Invalid salary '{}' on line {} – defaulting to 0", salStr, lineNo);
                    salary = BigDecimal.ZERO;
                }

                batch.add(Employee.builder()
                        .empId(empId)
                        .empName(empName)
                        .empDept(empDept)
                        .empSalary(salary)
                        .build());

                if (batch.size() == 500) {
                    employeeRepository.saveAll(batch);
                    batch.clear();
                }
            }
        }

        if (!batch.isEmpty()) {
            employeeRepository.saveAll(batch);
        }

        log.info("Loaded {} employee records from {}", lineNo, inputFilePath);
        return lineNo;
    }
}

