package com.example.deptsum.service;

import com.example.deptsum.domain.DepartmentSummary;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * Produces the deptsum.rpt fixed-width report.
 *
 * Reproduces every WRITE statement and the PRODUCE-REPORT / DEPT-BREAK
 * output formatting logic verbatim, including the COBOL picture clause
 * masks (ZZ9, ZZ,ZZZ,ZZ9.99, Z,ZZZ,ZZ9.99).
 */
@Slf4j
@Component
public class ReportWriter implements Closeable {

    // ---- Picture-clause column widths from DTL-LINE ----
    private static final int DTL_DEPT_W  = 12;   // PIC X(12)
    private static final int FILLER1_W   =  4;   // PIC X(04)
    private static final int DTL_COUNT_W =  3;   // PIC ZZ9
    private static final int FILLER2_W   =  5;   // PIC X(05)
    private static final int DTL_TOTAL_W = 12;   // ZZ,ZZZ,ZZ9.99
    private static final int FILLER3_W   =  5;   // PIC X(05)
    private static final int DTL_AVG_W   = 11;   // Z,ZZZ,ZZ9.99

    private static final String SEP_LINE =
            "-".repeat(60);
    private static final String HEADER_TITLE =
            "DEPARTMENT SALARY SUMMARY";
    // Reproduces HDR-1 exactly
    private static final String HDR_1 =
            String.format("%-12s%-10s%-18s%-18s",
                    "DEPARTMENT", "HEADCOUNT",
                    "     TOTAL SALARY", "    AVERAGE SALARY");

    @Value("${deptsum.output.file}")
    private String outputFilePath;

    private PrintWriter writer;

    /** Opens the output file – mirrors OPEN OUTPUT RPT-FILE. */
    public void open() throws IOException {
        Path out = Path.of(outputFilePath);
        Files.createDirectories(out.getParent());
        writer = new PrintWriter(new BufferedWriter(new FileWriter(out.toFile())));

        // WRITE RPT-LINE (title)
        writeLine(padRight(HEADER_TITLE, 80));
        // WRITE RPT-LINE FROM SEP-LINE
        writeLine(padRight(SEP_LINE, 80));
        // WRITE RPT-LINE FROM HDR-1
        writeLine(padRight(HDR_1, 80));
        // WRITE RPT-LINE FROM SEP-LINE
        writeLine(padRight(SEP_LINE, 80));
    }

    /** Writes one department detail line – mirrors WRITE RPT-LINE FROM DTL-LINE. */
    public void writeDeptLine(DepartmentSummary summary) {
        writeLine(formatDtlLine(
                summary.getDepartment(),
                summary.getHeadCount(),
                summary.getTotalSalary(),
                summary.getAvgSalary()));
    }

    /** Writes the grand-total (ALL DEPTS) line and separator. */
    public void writeGrandTotal(int grandCount, BigDecimal grandTotal) {
        // WRITE RPT-LINE FROM SEP-LINE
        writeLine(padRight(SEP_LINE, 80));

        // COMPUTE WS-DEPT-AVG ROUNDED = WS-GRAND-TOTAL / WS-GRAND-COUNT
        BigDecimal grandAvg = (grandCount > 0)
                ? grandTotal.divide(BigDecimal.valueOf(grandCount), 2, RoundingMode.HALF_UP)
                : BigDecimal.ZERO;

        writeLine(formatDtlLine("ALL DEPTS", grandCount, grandTotal, grandAvg));
    }

    // ---- Internal helpers ----

    private void writeLine(String line) {
        writer.println(line);
    }

    /**
     * Formats one DTL-LINE record:
     *   DTL-DEPT  PIC X(12)
     *   FILLER    PIC X(04) SPACES
     *   DTL-COUNT PIC ZZ9          (right-justified, leading-space suppressed)
     *   FILLER    PIC X(05) SPACES
     *   DTL-TOTAL PIC ZZ,ZZZ,ZZ9.99
     *   FILLER    PIC X(05) SPACES
     *   DTL-AVG   PIC Z,ZZZ,ZZ9.99
     */
    private String formatDtlLine(String dept, int count,
                                 BigDecimal total, BigDecimal avg) {
        String deptF  = padRight(dept, DTL_DEPT_W);
        String fill1  = " ".repeat(FILLER1_W);
        String countF = formatZZ9(count);
        String fill2  = " ".repeat(FILLER2_W);
        String totalF = formatZZZZZZ999_99(total);
        String fill3  = " ".repeat(FILLER3_W);
        String avgF   = formatZZZZZ99_99(avg);

        return deptF + fill1 + countF + fill2 + totalF + fill3 + avgF;
    }

    /** PIC ZZ9 – 3-char, leading zeros replaced by spaces. */
    private String formatZZ9(int value) {
        if (value > 999) value = 999; // overflow guard
        String s = String.format("%3d", value);
        return replaceLeadingZerosWithSpaces(s, false);
    }

    /** PIC ZZ,ZZZ,ZZ9.99 – 12-char with comma grouping. */
    private String formatZZZZZZ999_99(BigDecimal value) {
        // Format as 9999999999.99 then insert commas and suppress leading zeros/commas
        long cents = value.setScale(2, RoundingMode.HALF_UP)
                .movePointRight(2).longValue();
        // Max representable: 999,999,999.99 -> 12 chars
        long wholePart = cents / 100;
        long fracPart  = Math.abs(cents % 100);
        String numStr  = String.format("%,d.%02d", wholePart, fracPart);
        // Right-justify in 12 chars; replace leading zeros/commas with spaces
        String padded  = String.format("%12s", numStr);
        return suppressLeadingZeroComma(padded);
    }

    /** PIC Z,ZZZ,ZZ9.99 – 11-char with comma grouping. */
    private String formatZZZZZ99_99(BigDecimal value) {
        long cents = value.setScale(2, RoundingMode.HALF_UP)
                .movePointRight(2).longValue();
        long wholePart = cents / 100;
        long fracPart  = Math.abs(cents % 100);
        String numStr  = String.format("%,d.%02d", wholePart, fracPart);
        String padded  = String.format("%11s", numStr);
        return suppressLeadingZeroComma(padded);
    }

    /**
     * Mimics COBOL Z-picture: replace leading '0' and ',' chars with spaces
     * but preserve the last digit group and the decimal part.
     */
    private String suppressLeadingZeroComma(String s) {
        char[] chars = s.toCharArray();
        boolean leadingSpace = true;
        for (int i = 0; i < chars.length; i++) {
            if (leadingSpace) {
                if (chars[i] == ' ' || chars[i] == '0' || chars[i] == ',') {
                    chars[i] = ' ';
                } else if (chars[i] == '.') {
                    // e.g. ".99" – ensure zero before decimal
                    leadingSpace = false;
                } else {
                    leadingSpace = false;
                }
            }
        }
        return new String(chars);
    }

    private String replaceLeadingZerosWithSpaces(String s, boolean preserveLast) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length - 1; i++) {
            if (chars[i] == '0') chars[i] = ' ';
            else break;
        }
        return new String(chars);
    }

    private String padRight(String s, int width) {
        if (s == null) s = "";
        if (s.length() >= width) return s.substring(0, width);
        return s + " ".repeat(width - s.length());
    }

    /** Mirrors CLOSE RPT-FILE. */
    @Override
    public void close() {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }
}

