package com.example.deptsum.service;

import com.example.deptsum.domain.DepartmentSummary;
import com.example.deptsum.domain.Employee;
import com.example.deptsum.repository.EmployeeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Core orchestration service.
 *
 * Mirrors the COBOL MAIN-PARA → PRODUCE-REPORT →
 *   PROCESS-RECORD / DEPT-BREAK logic exactly:
 *
 *   - Sort by EMP-DEPT ASC, EMP-ID ASC  (done by the repository query)
 *   - Iterate records, detect department break, accumulate per-dept totals
 *   - On break: emit dept summary line (DEPT-BREAK), reset counters
 *   - After loop: emit final dept + grand-total (ALL DEPTS) lines
 *   - DISPLAY grand count to stdout (mirroring COBOL DISPLAY)
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class DeptSumService {

    private final EmployeeRepository employeeRepository;
    private final EmployeeFileParser fileParser;
    private final ReportWriter       reportWriter;

    // ---- WS equivalents ----
    private boolean wsFirst     = true;   // WS-FIRST PIC X VALUE 'Y'
    private String  wsPrevDept  = "";     // WS-PREV-DEPT
    private int     wsDeptCount = 0;      // WS-DEPT-COUNT
    private BigDecimal wsDeptTotal  = BigDecimal.ZERO; // WS-DEPT-TOTAL
    private int     wsGrandCount = 0;     // WS-GRAND-COUNT
    private BigDecimal wsGrandTotal = BigDecimal.ZERO; // WS-GRAND-TOTAL

    /**
     * Entry point – mirrors MAIN-PARA.
     */
    public void run() throws Exception {
        // Load flat file into PostgreSQL (replaces the COBOL SORT … USING EMP-FILE)
        fileParser.loadFile();

        // PRODUCE-REPORT (OUTPUT PROCEDURE)
        produceReport();

        // DISPLAY "DEPTSUM: " WS-GRAND-COUNT " RECORDS SUMMARISED"
        System.out.printf("DEPTSUM: %d RECORDS SUMMARISED%n", wsGrandCount);
    }

    // ------------------------------------------------------------------
    // PRODUCE-REPORT
    // ------------------------------------------------------------------
    private void produceReport() throws Exception {
        // Reset working-storage (supports multiple calls in test scenarios)
        resetWorkingStorage();

        // Fetch all employees sorted by dept then id
        // (mirrors SORT SORT-FILE ON ASCENDING KEY EMP-DEPT, EMP-ID)
        List<Employee> employees = employeeRepository.findAllSortedByDeptThenId();

        // OPEN OUTPUT RPT-FILE + write headers
        reportWriter.open();

        // PERFORM UNTIL END-OF-SORT … RETURN SORT-FILE
        for (Employee emp : employees) {
            processRecord(emp);
        }

        // IF WS-FIRST = 'N' PERFORM DEPT-BREAK
        if (!wsFirst) {
            deptBreak();
        }

        // Write grand-total line (ALL DEPTS)
        reportWriter.writeGrandTotal(wsGrandCount, wsGrandTotal);

        // CLOSE RPT-FILE
        reportWriter.close();
    }

    // ------------------------------------------------------------------
    // PROCESS-RECORD
    // ------------------------------------------------------------------
    private void processRecord(Employee emp) {
        // IF WS-FIRST = 'Y'
        if (wsFirst) {
            wsFirst    = false;                 // MOVE 'N' TO WS-FIRST
            wsPrevDept = emp.getEmpDept();      // MOVE EMP-DEPT TO WS-PREV-DEPT
        }

        // IF EMP-DEPT NOT = WS-PREV-DEPT
        if (!emp.getEmpDept().equals(wsPrevDept)) {
            deptBreak();                         // PERFORM DEPT-BREAK
            wsPrevDept = emp.getEmpDept();       // MOVE EMP-DEPT TO WS-PREV-DEPT
        }

        // ADD 1 TO WS-DEPT-COUNT WS-GRAND-COUNT
        wsDeptCount++;
        wsGrandCount++;

        // ADD EMP-SALARY TO WS-DEPT-TOTAL WS-GRAND-TOTAL
        wsDeptTotal  = wsDeptTotal.add(emp.getEmpSalary());
        wsGrandTotal = wsGrandTotal.add(emp.getEmpSalary());
    }

    // ------------------------------------------------------------------
    // DEPT-BREAK
    // ------------------------------------------------------------------
    private void deptBreak() {
        // COMPUTE WS-DEPT-AVG ROUNDED = WS-DEPT-TOTAL / WS-DEPT-COUNT
        BigDecimal wsDeptAvg = (wsDeptCount > 0)
                ? wsDeptTotal.divide(
                        BigDecimal.valueOf(wsDeptCount), 2, RoundingMode.HALF_UP)
                : BigDecimal.ZERO;

        DepartmentSummary summary = DepartmentSummary.builder()
                .department(wsPrevDept)
                .headCount(wsDeptCount)
                .totalSalary(wsDeptTotal)
                .avgSalary(wsDeptAvg)
                .build();

        // WRITE RPT-LINE FROM DTL-LINE
        reportWriter.writeDeptLine(summary);

        // MOVE 0 TO WS-DEPT-COUNT WS-DEPT-TOTAL
        wsDeptCount = 0;
        wsDeptTotal = BigDecimal.ZERO;
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------
    private void resetWorkingStorage() {
        wsFirst      = true;
        wsPrevDept   = "";
        wsDeptCount  = 0;
        wsDeptTotal  = BigDecimal.ZERO;
        wsGrandCount = 0;
        wsGrandTotal = BigDecimal.ZERO;
    }
}
